40	/****************************************************************************
41	 * Private Types
42	 ****************************************************************************/
43	
44	struct v_buffer
45	{
46	  uint8_t *start;
47	  uint32_t length;
48	};
49	
50	/****************************************************************************
51	 * Private Data
52	 ****************************************************************************/
53	
54	static struct fb_videoinfo_s g_vinfo;
55	static int                   g_fbfd = -1;
56	static int                   g_recfd = -1;  /* /data/capture.yuv */
57	static uint16_t              g_rgbbuf[TEST_WIDTH * TEST_HEIGHT];
