59	/****************************************************************************
60	 * tjpgd callbacks for MJPEG decode
61	 ****************************************************************************/
62	
63	struct mjpeg_iodev_s
64	{
65	  const uint8_t *data;
66	  size_t         len;
67	  size_t         pos;
68	};
69	
70	static size_t mjpeg_input(JDEC *jd, uint8_t *buff, size_t nbyte)
71	{
72	  struct mjpeg_iodev_s *io = (struct mjpeg_iodev_s *)jd->device;
73	  size_t avail = io->len - io->pos;
74	
75	  if (nbyte > avail)
76	    nbyte = avail;
77	
78	  if (buff)
79	    memcpy(buff, io->data + io->pos, nbyte);
80	
81	  io->pos += nbyte;
82	  return nbyte;
83	}
84	
85	static int mjpeg_output(JDEC *jd, void *bitmap, JRECT *rect)
86	{
87	  uint8_t *src = (uint8_t *)bitmap;
88	  uint32_t x;
89	  uint32_t y;
90	  uint32_t w = rect->right - rect->left + 1;
91	  uint32_t cpw = jd->width < TEST_WIDTH ? jd->width : TEST_WIDTH;
92	
93	  for (y = rect->top; y <= rect->bottom && y < TEST_HEIGHT; y++)
94	    {
95	      for (x = rect->left; x <= rect->right && x < TEST_WIDTH; x++)
96	        {
97	          uint8_t b = *src++;
98	          uint8_t g = *src++;
99	          uint8_t r = *src++;
100	          g_rgbbuf[y * cpw + x] =
101	            ((r & 0xf8) << 8) | ((g & 0xfc) << 3) | (b >> 3);
102	        }
103	
104	      if (rect->right >= TEST_WIDTH)
105	        src += (rect->right - TEST_WIDTH + 1) * 3;
106	    }
107	
108	  return 1;
109	}
