141	 * Description:
142	 *   Open the framebuffer device and query its geometry.
143	 *
144	 ****************************************************************************/
145	
146	static int fb_open(void)
147	{
148	  int ret;
149	
150	  g_fbfd = open(FB_DEV_PATH, O_RDWR);
151	  if (g_fbfd < 0)
152	    {
153	      printf("ERROR: open %s failed: %d\n", FB_DEV_PATH, errno);
154	      return -errno;
155	    }
156	
157	  /* /dev/lcd0 is an lcddev character device, use LCDDEVIO_GETVIDEOINFO */
158	
159	  ret = ioctl(g_fbfd, LCDDEVIO_GETVIDEOINFO, (uintptr_t)&g_vinfo);
160	  if (ret < 0)
161	    {
162	      printf("ERROR: LCDDEVIO_GETVIDEOINFO failed: %d\n", errno);
163	      close(g_fbfd);
164	      g_fbfd = -1;
165	      return -errno;
166	    }
167	
168	  printf("LCD: %ux%u fmt=%u\n", g_vinfo.xres, g_vinfo.yres, g_vinfo.fmt);
169	
170	  /* Also emit to syslog so it lands in the serial log for diagnosis. */
171	
172	  syslog(LOG_ERR, "UVCTEST LCD: xres=%u yres=%u fmt=%u\n",
173	         g_vinfo.xres, g_vinfo.yres, g_vinfo.fmt);
174	
175	  return OK;
176	}
