178	/****************************************************************************
179	 * Name: fb_update
180	 *
181	 * Description:
182	 *   Notify the framebuffer driver that the content changed (for LCD
183	 *   drivers that need an explicit flush).
184	 *
185	 ****************************************************************************/
186	
187	static void fb_blit(uint32_t w, uint32_t h)
188	{
189	  struct lcddev_area_s area;
190	
191	  memset(&area, 0, sizeof(area));
192	  area.row_start = 0;
193	  area.row_end   = h - 1;
194	  area.col_start = 0;
195	  area.col_end   = w - 1;
196	  area.stride    = w * 2;          /* RGB565: 2 bytes/pixel */
197	  area.data      = (FAR uint8_t *)g_rgbbuf;
198	
199	  ioctl(g_fbfd, LCDDEVIO_PUTAREA, (uintptr_t)&area);
200	}
