279	  /* DIAG: draw a static test pattern (colored horizontal bars) once, before
280	   * any camera data, to isolate the blit/LCD path from the camera data.  If
281	   * these bars appear clean and aligned, the LCD geometry+blit is correct and
282	   * any stripes are in the camera-frame layout; if the bars themselves are
283	   * striped/torn, the problem is in the blit or LCD driver path.
284	   */
285	
286	  {
287	    uint32_t pw = (g_vinfo.xres > 0) ? g_vinfo.xres : TEST_WIDTH;
288	    uint32_t ph = (g_vinfo.yres > 0) ? g_vinfo.yres : TEST_HEIGHT;
289	    uint32_t xx;
290	    uint32_t yy;
291	
292	    if (pw > TEST_WIDTH)  pw = TEST_WIDTH;
293	    if (ph > TEST_HEIGHT) ph = TEST_HEIGHT;
294	
295	    for (yy = 0; yy < ph; yy++)
296	      {
297	        uint16_t color;
298	        if      (yy < ph / 4)     color = 0xf800;  /* red    */
299	        else if (yy < ph / 2)     color = 0x07e0;  /* green  */
300	        else if (yy < ph * 3 / 4) color = 0x001f;  /* blue   */
301	        else                      color = 0xffff;  /* white  */
302	
303	        for (xx = 0; xx < pw; xx++)
304	          {
305	            g_rgbbuf[yy * pw + xx] = color;
306	          }
307	      }
308	
309	    fb_blit(pw, ph);
310	    syslog(LOG_ERR, "UVCTEST testpattern blitted %ux%u\n", pw, ph);
311	    sleep(2);
312	  }
313	
314	  /* Initialize video driver (creates /dev/video device) */
315	
316	  ret = capture_initialize(VIDEO_DEV_PATH);
317	  if (ret != 0)
318	    {
319	      printf("ERROR: Failed to initialize video: %d (errno=%d)\n", ret, errno);
320	      return ERROR;
321	    }
322	
323	  fd = open(VIDEO_DEV_PATH, O_RDWR);
324	  if (fd < 0)
325	    {
326	      printf("ERROR: Failed to open %s: %d\n", VIDEO_DEV_PATH, errno);
327	      return ERROR;
328	    }
329	
330	  /* Set YUYV format */
331	
332	  memset(&fmt, 0, sizeof(fmt));
333	  fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
334	  fmt.fmt.pix.width = TEST_WIDTH;
335	  fmt.fmt.pix.height = TEST_HEIGHT;
336	  fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
337	  fmt.fmt.pix.field = V4L2_FIELD_NONE;
338	
339	  ret = ioctl(fd, VIDIOC_S_FMT, (uintptr_t)&fmt);
340	  if (ret < 0)
341	    {
342	      printf("ERROR: VIDIOC_S_FMT failed: %d\n", errno);
343	      goto err_close;
344	    }
345	
346	  if (fmt.fmt.pix.sizeimage == 0)
347	    {
348	      fmt.fmt.pix.sizeimage = TEST_WIDTH * TEST_HEIGHT * 2;
349	    }
350	
351	  /* Request buffers */
352	
353	  memset(&req, 0, sizeof(req));
354	  req.count = TEST_BUF_COUNT;
355	  req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
356	  req.memory = V4L2_MEMORY_USERPTR;
357	
358	  ret = ioctl(fd, VIDIOC_REQBUFS, (uintptr_t)&req);
359	  if (ret < 0)
360	    {
361	      printf("ERROR: VIDIOC_REQBUFS failed: %d\n", errno);
362	      goto err_close;
363	    }
364	
365	  buffers = (struct v_buffer *)malloc(req.count * sizeof(struct v_buffer));
366	  if (buffers == NULL)
367	    {
368	      printf("ERROR: Failed to allocate buffer array\n");
369	      goto err_close;
370	    }
371	
372	  for (i = 0; i < req.count; i++)
373	    {
374	      buffers[i].length = fmt.fmt.pix.sizeimage;
375	      buffers[i].start = (uint8_t *)memalign(64, buffers[i].length);
376	      if (buffers[i].start == NULL)
377	        {
378	          printf("ERROR: Failed to allocate buffer %d\n", i);
379	          goto err_free_buffers;
380	        }
381	
382	      memset(&buf, 0, sizeof(buf));
383	      buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
384	      buf.memory = V4L2_MEMORY_USERPTR;
385	      buf.index = i;
386	      buf.m.userptr = (uintptr_t)buffers[i].start;
387	      buf.length = buffers[i].length;
388	
389	      ret = ioctl(fd, VIDIOC_QBUF, (uintptr_t)&buf);
390	      if (ret < 0)
391	        {
392	          printf("ERROR: VIDIOC_QBUF failed for buffer %d: %d\n", i, errno);
393	          goto err_free_buffers;
394	        }
395	    }
396	
397	  /* Start streaming */
398	
399	  ret = ioctl(fd, VIDIOC_STREAMON, (uintptr_t)&type);
400	  if (ret < 0)
401	    {
402	      printf("ERROR: VIDIOC_STREAMON failed: %d\n", errno);
403	      goto err_free_buffers;
404	    }
405	
406	  printf("Live preview started (press Ctrl-C to stop)\n");
407	
408	  /* Preview loop */
409	
410	  {
411	    struct timeval fps_tv;
412	    int fps_count = 0;
413	    uint32_t us_dqbuf = 0;   /* accumulated DQBUF wait (us)   */
414	    uint32_t us_decode = 0;  /* accumulated JPEG decode (us)  */
415	    uint32_t us_blit = 0;    /* accumulated LCD blit (us)     */
416	    struct timeval t_prev;   /* end of previous iteration     */
417	
418	    gettimeofday(&fps_tv, NULL);
419	    gettimeofday(&t_prev, NULL);
420	
421	  while (PREVIEW_FRAMES == 0 || frames < PREVIEW_FRAMES)
422	    {
423	      struct timeval ta;
424	      struct timeval tb;
425	
426	      memset(&buf, 0, sizeof(buf));
427	      buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
428	      buf.memory = V4L2_MEMORY_USERPTR;
429	
430	      ret = ioctl(fd, VIDIOC_DQBUF, (uintptr_t)&buf);
431	      if (ret < 0)
432	        {
433	          printf("ERROR: VIDIOC_DQBUF failed: %d\n", errno);
434	          break;
435	        }
436	
437	      /* DQBUF returned — time spent waiting for a frame since last loop end */
438	
439	      gettimeofday(&ta, NULL);
440	      us_dqbuf += (ta.tv_sec - t_prev.tv_sec) * 1000000 +
441	                  (ta.tv_usec - t_prev.tv_usec);
442	
443	      /* FPS + per-stage timing: print once per second */
444	
445	      {
446	        fps_count++;
447	        if (ta.tv_sec > fps_tv.tv_sec)
448	          {
449	            int c = fps_count > 0 ? fps_count : 1;
450	            syslog(LOG_ERR,
451	              "FPS: %d  avg_us: dqbuf=%u decode=%u blit=%u\n",
452	              fps_count, us_dqbuf / c, us_decode / c, us_blit / c);
453	            fps_count = 0;
454	            us_dqbuf = us_decode = us_blit = 0;
455	            fps_tv = ta;
456	          }
457	      }
458	
459	      /* Snapshot the frame into a private buffer, then IMMEDIATELY requeue
460	       * the V4L2 buffer.  The UVC stream thread writes the next frame into
461	       * one of the shared capture buffers concurrently; if the app kept a
462	       * buffer for the whole convert+SPI-blit time (slow, per-row SPI), the
463	       * driver could wrap around and overwrite the buffer mid-read, showing
464	       * up as a moving horizontal "tear" band.  Copying out fast (one memcpy)
465	       * and requeuing at once shrinks that window to almost nothing.
466	       */
467	
468	      {
469	        uint32_t n = buf.bytesused;
470	        if (n > sizeof(g_framecopy))
471	          {
472	            n = sizeof(g_framecopy);
473	          }
474	
475	        memcpy(g_framecopy, (const void *)buf.m.userptr, n);
476	
477	        /* Requeue immediately, before the slow convert + blit. */
478	
479	        ret = ioctl(fd, VIDIOC_QBUF, (uintptr_t)&buf);
480	        if (ret < 0)
481	          {
482	            printf("ERROR: VIDIOC_QBUF failed: %d\n", errno);
483	            break;
484	          }
485	
486	      /* MJPEG: decode JPEG via tjpgd and blit to LCD. */
487	
488	      if (n > 1024)
489	        {
490	          static uint8_t jdwork[4096];  /* tjpgd work buffer */
491	          JDEC jdec;
492	          JRESULT res;
493	          struct mjpeg_iodev_s iodev;
494	
495	          iodev.data = g_framecopy;
496	          iodev.len  = n;
497	          iodev.pos  = 0;
498	
499	          res = jd_prepare(&jdec, mjpeg_input, jdwork,
500	                           sizeof(jdwork), &iodev);
501	          if (res == JDR_OK)
502	            {
503	              gettimeofday(&tb, NULL);
504	              jd_decomp(&jdec, mjpeg_output, 0);
505	
506	              {
507	                struct timeval tc;
508	                gettimeofday(&tc, NULL);
509	                us_decode += (tc.tv_sec - tb.tv_sec) * 1000000 +
510	                             (tc.tv_usec - tb.tv_usec);
511	
512	                fb_blit(jdec.width < TEST_WIDTH ? jdec.width : TEST_WIDTH,
513	                        jdec.height < TEST_HEIGHT ? jdec.height : TEST_HEIGHT);
514	
515	                {
516	                  struct timeval td;
517	                  gettimeofday(&td, NULL);
518	                  us_blit += (td.tv_sec - tc.tv_sec) * 1000000 +
519	                             (td.tv_usec - tc.tv_usec);
520	                }
521	              }
522	            }
523	        }
524	
525	      frames++;
526	
527	      gettimeofday(&t_prev, NULL);  /* mark end of this iteration */
528	
529	      }
530	    }
531	  }  /* fps_tv scope */
532	
533	  /* Stop streaming */
534	
535	  ioctl(fd, VIDIOC_STREAMOFF, (uintptr_t)&type);
536	  printf("Preview stopped after %d frames\n", frames);
537	
538	  /* Uninitialize video driver so /dev/video can be re-opened. */
539	
540	  capture_uninitialize(VIDEO_DEV_PATH);
