    {
      /* Non-contiguous: send row by row (still saves address-window
       * overhead vs. the per-row putrun emulation).
       */

      FAR const uint8_t *rowp = buffer;
      size_t r;

      for (r = 0; r < rows; r++)
        {
          lcd->sendgram(lcd, (FAR const uint16_t *)rowp, cols);
          rowp += stride;
        }
    }

